package vn.codegym.salesinventory.dao;

import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import vn.codegym.salesinventory.service.*;
import vn.codegym.salesinventory.validation.CommandConflictException;
import static org.assertj.core.api.Assertions.*;

class MvpCreditAcceptanceIT extends MvpWorkflowSupport {
    long accountant,wm;InvoiceService invoices;PaymentService payments;ReturnService returns;
    @BeforeEach void accounting(){accountant=user("ACCOUNTANT");wm=warehouseManager();invoices=new InvoiceService(source,clock);payments=new PaymentService(source,clock);returns=new ReturnService(source,clock);}
    long delivered(String qty){long shipment=dispatched(qty,qty);fulfillment.deliver(worker,shipment,1,key(),"Người nhận",received(shipment,qty),"");return shipment;}
    long invoice(String qty){return invoices.issue(accountant,delivered(qty),2,key());}
    long pay(String amount){long version=Sql.id(one("SELECT version FROM dealers WHERE id=?",dealer).get("version"));return payments.record(accountant,dealer,version,key(),new PaymentService.Input(new BigDecimal(amount),MvpCommands.date(now),"CASH","Thu theo chứng từ"));}
    long returnDraft(long invoice,String quantity,String condition){long line=Sql.id(one("SELECT id FROM mvp_invoice_lines WHERE invoice_id=? ORDER BY id",invoice).get("id"));return returns.save(sales,0,0,key(),new ReturnService.Input(invoice,"Trả hàng theo hóa đơn gốc",List.of(new ReturnService.Line(line,new BigDecimal(quantity),condition))));}
    long credited(long invoice,String qty,String condition){long id=returnDraft(invoice,qty,condition);returns.receive(wm,id,1,key(),true);returns.issueCredit(accountant,id,2,key());return id;}
    CreditService.CreditSnapshot credit(){return Sql.snapshot(source,c->CreditService.snapshot(c,dealer,now));}
    long oldCredit(){long original=invoice("1");pay("100000");credited(original,"1","DAMAGED");assertThat(credit().credit()).isEqualByComparingTo("100000");return original;}
    @Test void customerCreditCannotOffsetAnotherCustomersInvoiceOrReportOutstanding(){oldCredit();long firstDealer=dealer,territory=Sql.id(one("SELECT territory_id FROM dealers WHERE id=?",dealer).get("territory_id"));String marker="Đối chiếu "+UUID.randomUUID();update("UPDATE dealers SET name=? WHERE id=?",marker+" A",dealer);dealer=new DealerService(source).save(manager,0,new DealerService.Input("D-"+key(),marker+" B","","0912345678",group,territory,sales,warehouse,"ACTIVE",0));address=new DealerAddressService(source).save(manager,dealer,0,new DealerAddressService.Input("Điểm giao B","Người nhận","0912345678","",true,"ACTIVE",0,1));update("UPDATE dealers SET credit_limit=2000000,debt_days=30 WHERE id=?",dealer);long issued=invoice("1.5");assertThat((BigDecimal)invoices.invoice(accountant,issued).get("allocated")).isEqualByComparingTo("0");var firstCredit=Sql.snapshot(source,c->CreditService.snapshot(c,firstDealer,now));assertThat(firstCredit.credit()).isEqualByComparingTo("100000");assertThat(credit().outstanding()).isEqualByComparingTo("150000");var report=new SalesDebtReportService(source,clock).debt(accountant,null,marker);assertThat(report.rows()).hasSize(2);assertThat(report.totals().get("outstanding")).isEqualByComparingTo("150000");assertThat(report.totals().get("credit")).isEqualByComparingTo("100000");}
    @Test void reversingOriginalPaymentAfterCreditWasAppliedRestoresNewInvoiceDebtWithoutChangingSales(){oldCredit();long invoice=invoice("0.8");var doc=invoices.invoice(accountant,invoice);assertThat((BigDecimal)doc.get("applied_credit_at_issue")).isEqualByComparingTo("80000");assertThat(credit().credit()).isEqualByComparingTo("20000");long payment=Sql.id(one("SELECT id FROM mvp_payments WHERE dealer_id=?",dealer).get("id"));long countBefore=count("SELECT COUNT(*) n FROM mvp_payment_allocations WHERE invoice_id=?",invoice);String k=key();payments.reverse(accountant,payment,1,k,"Đối chiếu lại tiền nhận");payments.reverse(accountant,payment,1,k,"Đối chiếu lại tiền nhận");assertThat(credit().outstanding()).isEqualByComparingTo("80000");assertThat(credit().credit()).isEqualByComparingTo("0");assertThat((BigDecimal)invoices.invoice(accountant,invoice).get("allocated")).isEqualByComparingTo("0");assertThat(count("SELECT COUNT(*) n FROM mvp_payment_allocations WHERE invoice_id=?",invoice)).isGreaterThan(countBefore);assertThat(count("SELECT COUNT(*) n FROM mvp_payments WHERE dealer_id=?",dealer)).isEqualTo(1);var salesReport=new SalesDebtReportService(source,clock).sales(accountant,LocalDate.of(2027,1,1),LocalDate.of(2027,1,31),dealer,"");assertThat(salesReport.totals().get("net_sales")).isEqualByComparingTo("80000");}
    @Test void fractionalDispatchesAndReturnsReconcileLastRemainderAtFourDecimalPlaces(){new PricingService(source).saveItem(manager,priceVersion,product,new BigDecimal("333.3333"),BigDecimal.ZERO);long order=accepted("1");fulfillment.startPicking(worker,order,2,key());var documents=new ArrayList<Long>();for(String qty:List.of("0.333333","0.333333","0.333334")){long version=Sql.id(one("SELECT version FROM orders WHERE id=?",order).get("version"));long shipment=fulfillment.dispatch(worker,order,version,key(),take(order,qty),"Giao từng phần");fulfillment.deliver(worker,shipment,1,key(),"Người nhận",received(shipment,qty),"");documents.add(invoices.issue(accountant,shipment,2,key()));}assertThat(credit().outstanding()).isEqualByComparingTo("333.3333");assertThat(credit().commitment()).isEqualByComparingTo("0");pay("333.3333");long first=documents.get(0);for(int i=0;i<3;i++)credited(first,"0.111111","DAMAGED");BigDecimal original=(BigDecimal)one("SELECT net_amount FROM mvp_invoices WHERE id=?",first).get("net_amount");assertThat(credit().credit()).isEqualByComparingTo(original);assertThat(balance().onHand()).isEqualByComparingTo("19");long next=invoice("1");assertThat((BigDecimal)invoices.invoice(accountant,next).get("allocated")).isEqualByComparingTo(original);assertThat(credit().outstanding()).isEqualByComparingTo(new BigDecimal("333.3333").subtract(original));assertThat(count("SELECT COUNT(*) n FROM mvp_payments WHERE dealer_id=?",dealer)).isEqualTo(1);}
    @Test void goldenReceiptOrderPartialDeliveryPaymentGoodReturnAndFinalPaymentBalancesExactly(){long order=accepted("10");fulfillment.startPicking(worker,order,2,key());long shipment=fulfillment.dispatch(worker,order,3,key(),take(order,"8"),"Giao trước8");fulfillment.deliver(worker,shipment,1,key(),"Khách",received(shipment,"8"),"");long first=invoices.issue(accountant,shipment,2,key());pay("300000");assertThat(credit().outstanding()).isEqualByComparingTo("500000");long returned=returnDraft(first,"2","SELLABLE");returns.receive(wm,returned,1,key(),true);assertThat(balance().onHand()).isEqualByComparingTo("14");assertThat(credit().outstanding()).isEqualByComparingTo("500000");returns.issueCredit(accountant,returned,2,key());assertThat(credit().outstanding()).isEqualByComparingTo("300000");
        long last=fulfillment.dispatch(worker,order,5,key(),take(order,"2"),"");fulfillment.deliver(worker,last,1,key(),"Khách",received(last,"2"),"");invoices.issue(accountant,last,2,key());assertThat(credit().outstanding()).isEqualByComparingTo("500000");pay("500000");assertThat(credit().outstanding()).isEqualByComparingTo("0");assertThat(credit().commitment()).isEqualByComparingTo("0");assertThat(balance().onHand()).isEqualByComparingTo("12");assertThat(balance().reserved()).isEqualByComparingTo("0");
        BigDecimal netSales=(BigDecimal)one("SELECT (SELECT SUM(net_amount) FROM mvp_invoices WHERE dealer_id=?)-(SELECT SUM(amount) FROM mvp_credits WHERE dealer_id=?) amount",dealer,dealer).get("amount");assertThat(netSales).isEqualByComparingTo("800000");assertThat((BigDecimal)one("SELECT SUM(amount) amount FROM mvp_payments WHERE dealer_id=?",dealer).get("amount")).isEqualByComparingTo("800000");
    }
    @Test void damagedReturnReducesDebtAtOriginalPriceWithoutChangingStockAndCannotCreditBeforeReception(){long invoice=invoice("8");long id=returnDraft(invoice,"2","DAMAGED");assertThatThrownBy(()->returns.issueCredit(accountant,id,1,key())).isInstanceOf(IllegalArgumentException.class);returns.receive(wm,id,1,key(),true);var later=Clock.fixed(now.plus(Duration.ofDays(31)),ZoneOffset.UTC);var pricing=new PricingService(source);long next=pricing.create(manager,group,"Giá mới",LocalDate.of(2027,2,1),LocalDate.of(2027,2,28),priceVersion);pricing.saveItem(manager,next,product,new BigDecimal("150000"),new BigDecimal("50000"));String k=key();long credit=new ReturnService(source,later).issueCredit(accountant,id,2,k);assertThat(new ReturnService(source,later).issueCredit(accountant,id,2,k)).isEqualTo(credit);assertThat((BigDecimal)one("SELECT amount FROM mvp_credits WHERE id=?",credit).get("amount")).isEqualByComparingTo("200000");assertThat(credit().outstanding()).isEqualByComparingTo("600000");assertThat(balance().onHand()).isEqualByComparingTo("12");assertThat(balance().reserved()).isEqualByComparingTo("0");assertThatThrownBy(()->returns.issueCredit(sales,id,3,key())).isInstanceOf(SecurityException.class);
    }
    @Test void creditHundredAutomaticallyPaysEightyAndLeavesTwentyWithoutNewPayment(){oldCredit();long invoice=invoice("0.8");assertThat(credit().outstanding()).isEqualByComparingTo("0");assertThat(credit().credit()).isEqualByComparingTo("20000");assertThat(Sql.<BigDecimal>snapshot(source,c->CreditService.invoiceAllocated(c,invoice))).isEqualByComparingTo("80000");assertThat(count("SELECT COUNT(*) n FROM mvp_payments WHERE dealer_id=?",dealer)).isEqualTo(1);assertThat((BigDecimal)invoices.invoice(accountant,invoice).get("outstanding")).isEqualByComparingTo("0");
    }
    @Test void creditHundredAgainstInvoiceOneHundredFiftyLeavesOnlyFiftyCollectible(){oldCredit();long invoice=invoice("1.5");assertThat(credit().outstanding()).isEqualByComparingTo("50000");assertThat(Sql.<BigDecimal>snapshot(source,c->CreditService.invoiceAllocated(c,invoice))).isEqualByComparingTo("100000");assertThatThrownBy(()->pay("50001")).isInstanceOf(IllegalArgumentException.class);pay("50000");assertThat(credit().outstanding()).isEqualByComparingTo("0");
    }
    @Test void twoEightyInvoicesCompeteForOnlyHundredCredit()throws Exception{oldCredit();long first=delivered("0.8"),second=delivered("0.8");var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);
        try{var one=pool.submit(()->{barrier.await();return invoices.issue(accountant,first,2,key());});var two=pool.submit(()->{barrier.await();return invoices.issue(accountant,second,2,key());});long a=one.get(30,TimeUnit.SECONDS),b=two.get(30,TimeUnit.SECONDS);assertThat(Sql.<BigDecimal>snapshot(source,c->CreditService.invoiceAllocated(c,a).add(CreditService.invoiceAllocated(c,b)))).isEqualByComparingTo("100000");assertThat(credit().outstanding()).isEqualByComparingTo("60000");assertThat(count("SELECT COUNT(*) n FROM mvp_payments WHERE dealer_id=?",dealer)).isEqualTo(1);}finally{pool.shutdownNow();}
    }
    @Test void invoiceCreditRetryAndAuditFailureCannotConsumeCreditOrLoseCounter(){oldCredit();long shipment=delivered("0.8");long before=Sql.id(one("SELECT next_value FROM mvp_sequences WHERE kind='HD' AND document_year=2027").get("next_value"));update("CREATE TRIGGER fail_credit_invoice BEFORE INSERT ON audit_logs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='audit failed'");
        try{assertThatThrownBy(()->invoices.issue(accountant,shipment,2,key())).isInstanceOf(IllegalStateException.class);}finally{update("DROP TRIGGER fail_credit_invoice");}assertThat(credit().credit()).isEqualByComparingTo("100000");assertThat(credit().commitment()).isEqualByComparingTo("80000");assertThat(Sql.id(one("SELECT next_value FROM mvp_sequences WHERE kind='HD' AND document_year=2027").get("next_value"))).isEqualTo(before);String k=key();long id=invoices.issue(accountant,shipment,2,k);assertThat(invoices.issue(accountant,shipment,2,k)).isEqualTo(id);assertThat(credit().credit()).isEqualByComparingTo("20000");assertThat(credit().commitment()).isEqualByComparingTo("0");
    }
    @Test void creditAuditFailureRollsBackDebtSourceVersionAndAllocationHistory(){long invoice=invoice("1");pay("100000");long id=returnDraft(invoice,"1","DAMAGED");returns.receive(wm,id,1,key(),true);long allocations=count("SELECT COUNT(*) n FROM mvp_payment_allocations a JOIN mvp_invoices i ON i.id=a.invoice_id WHERE i.dealer_id=?",dealer);update("CREATE TRIGGER fail_return_credit BEFORE INSERT ON audit_logs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='audit failed'");
        try{assertThatThrownBy(()->returns.issueCredit(accountant,id,2,key())).isInstanceOf(IllegalStateException.class);}finally{update("DROP TRIGGER fail_return_credit");}assertThat(credit().credit()).isEqualByComparingTo("0");assertThat(credit().outstanding()).isEqualByComparingTo("0");assertThat(count("SELECT COUNT(*) n FROM mvp_credits WHERE return_id=?",id)).isZero();assertThat(Sql.id(one("SELECT version FROM mvp_returns WHERE id=?",id).get("version"))).isEqualTo(2);assertThat(count("SELECT COUNT(*) n FROM mvp_payment_allocations a JOIN mvp_invoices i ON i.id=a.invoice_id WHERE i.dealer_id=?",dealer)).isEqualTo(allocations);
    }
}
